#include <game/pxdvs/app/battleGrid/battleGridPrivate.hpp>
#include <libc/string.h>
extern "C" {void GSlogWrite(const char*);void Sequence_CopyState(NullSequence*,NullSequence*);s32 wazaSequenceSysGetActiveWazaNum();}
BattleGrid gBattleGrid;
static bool gSavedVisibilityCodes[12],gBackupVisibilityCodes[12];
static s32 g_max_model_size;static bool gVisibilityChanged,gVisibilityBackedUp;
static inline ModelSequence *asModel(NullSequence *sequence){if(sequence==0)return 0;if(sequence->type==1)return static_cast<ModelSequence*>(sequence);return 0;}
static inline void lookSource(ModelSequence *model,ModelSequence *source){if(model->lookSource)model->lookSource->lookTarget=0;if(!model->isPokemon)source=0;model->lookSource=source;}
static inline void placeModel(ModelSequence *model,GSvec *position,GSvec *rotation,u8 flipped){if(model){model->SetPosition(position);model->SetRotation(rotation);model->flipped=flipped;}}
static inline f32 modelScale(){switch(g_max_model_size){case -2:case -1:return .875f;case 1:return 1.4f;case 2:return 1.8f;case 3:return 2.4f;default:return 1.0f;}}
extern "C" {
BattleGrid *battleGridGetPtr(){return &gBattleGrid;}
u16 battleGridGetNumPokemonsForTrainer(NullSequence *sequence){BattleGridTrainer *entry=gBattleGrid.trainers;ModelSequence *trainer=asModel(sequence);if(!trainer)return 0;for(u16 i=0;i<4;i++,entry++){if(entry->trainer==trainer)return entry->count;}return 0;}
void battleGridRestoreModelVisibilityFlags(){BattleGridTrainer *entry=gBattleGrid.trainers;u16 i,j;u16 index=0;if(gVisibilityBackedUp){for(i=0;i<4;i++,entry++){if(entry->trainer)entry->trainer->NullSequence::SetVisibility(gBackupVisibilityCodes[index]);index++;for(j=0;j<2;j++){if(entry->pokemon[j])entry->pokemon[j]->NullSequence::SetVisibility(gBackupVisibilityCodes[index]);index++;}}gVisibilityBackedUp=0;memcpy(gSavedVisibilityCodes,gBackupVisibilityCodes,12);}}
void battleGridBackupModelVisibilityFlags(){u16 index=0;BattleGridTrainer *entry=gBattleGrid.trainers;memset(gBackupVisibilityCodes,0,12);for(u16 i=0;i<4;i++,entry++){if(entry->trainer)gBackupVisibilityCodes[index]=entry->trainer->visible;index++;for(u16 j=0;j<2;j++){if(entry->pokemon[j])gBackupVisibilityCodes[index]=entry->pokemon[j]->visible;index++;}}gVisibilityBackedUp=1;}
void battleGridResetModelVisibilityFlags(){BattleGridTrainer *entry=gBattleGrid.trainers;u16 i,j;u16 index=0;if(gVisibilityChanged){for(i=0;i<4;i++,entry++){if(entry->trainer)entry->trainer->NullSequence::SetVisibility(gSavedVisibilityCodes[index]);index++;for(j=0;j<2;j++){if(entry->pokemon[j])entry->pokemon[j]->NullSequence::SetVisibility(gSavedVisibilityCodes[index]);index++;}}gVisibilityChanged=0;}}
void battleGridStoreModelVisibilityFlags(){u16 index=0;BattleGridTrainer *entry=gBattleGrid.trainers;memset(gSavedVisibilityCodes,0,12);for(u16 i=0;i<4;i++,entry++){if(entry->trainer)gSavedVisibilityCodes[index]=entry->trainer->visible;index++;for(u16 j=0;j<2;j++){if(entry->pokemon[j])gSavedVisibilityCodes[index]=entry->pokemon[j]->visible;index++;}}gVisibilityChanged=1;}
void battleGridHideModelsExcept(NullSequence *sequence){BattleGridTrainer *entry=gBattleGrid.trainers;u16 index=0;ModelSequence *keep=asModel(sequence);battleGridResetModelVisibilityFlags();memset(gSavedVisibilityCodes,0,12);for(u16 i=0;i<4;i++,entry++){ModelSequence *model=entry->trainer;if(model){gSavedVisibilityCodes[index]=model->visible;if(model!=keep)model->SetVisibility(0);}index++;for(u16 j=0;j<2;j++){model=entry->pokemon[j];if(model){gSavedVisibilityCodes[index]=model->visible;if(model!=keep)model->SetVisibility(0);}index++;}}gVisibilityChanged=1;}
void battleGridReset(){memset(&gBattleGrid,0,0x44);g_max_model_size=0;gVisibilityChanged=0;}
void battleGridUpdate(){u16 count=gBattleGrid.trainerCount;BattleGridTrainer *entry=gBattleGrid.trainers;wazaSequenceSysGetActiveWazaNum();if(count){g_max_model_size=-2;u8 found=0;for(u16 i=0;i<4;i++){if(gBattleGrid.trainers[i].trainer){ModelSequence **models=gBattleGrid.trainers[i].pokemon;for(u16 j=0;j<2;j++,models++){ModelSequence *model=*models;if(model){s8 size=model->modelSize;found=1;if(size>g_max_model_size)g_max_model_size=size;}}}}if(!found)g_max_model_size=0;f32 scale=modelScale();f32 negative=-scale;f32 spacing=30.0f*scale;GSvec trainerPosition={0,0,0},pokemonPosition={0,0,0},rotation={0,0,0};for(u16 i=0;i<4;i++,entry++){if(entry->trainer){lookSource(entry->trainer,0);if(entry->side){trainerPosition.x=65.0f*negative;pokemonPosition.x=40.0f*negative;rotation.y=1.5707964f;}else{trainerPosition.x=65.0f*scale;pokemonPosition.x=40.0f*scale;rotation.y=-1.5707964f;}f32 z=-30.0f*scale*entry->lane;trainerPosition.z=z;pokemonPosition.z=z;switch(entry->count){case 1:trainerPosition.z=z+(-12.5f*scale);if(entry->pokemon[0]){lookSource(entry->pokemon[0],entry->trainer);placeModel(entry->pokemon[0],&pokemonPosition,&rotation,entry->side);}else{lookSource(entry->pokemon[1],entry->trainer);placeModel(entry->pokemon[1],&pokemonPosition,&rotation,entry->side);}break;case 2:{GSvec position=pokemonPosition;position.z=z;lookSource(entry->pokemon[0],entry->trainer);lookSource(entry->pokemon[1],entry->trainer);if(entry->side){position.z=pokemonPosition.z-spacing;placeModel(entry->pokemon[0],&position,&rotation,entry->side);position.z=pokemonPosition.z+spacing;placeModel(entry->pokemon[1],&position,&rotation,entry->side);}else{position.z=pokemonPosition.z-spacing;placeModel(entry->pokemon[1],&position,&rotation,entry->side);position.z=pokemonPosition.z+spacing;placeModel(entry->pokemon[0],&position,&rotation,entry->side);}break;}}placeModel(entry->trainer,&trainerPosition,&rotation,entry->side);entry->trainer->NullSequence::SetVisibility(1);}}}}
f32 battleGridGetUnscaledDistance(u8 pokemon){if(pokemon)return 40.0f;return 65.0f;}
f32 battleGridGetDistance(u8 pokemon){f32 scale=modelScale();if(pokemon)return 40.0f*scale;return 65.0f*scale;}
void battleGridGetNormalisedScale(GSvec *out){f32 value=1.7105263f*modelScale();out->x=value;out->y=value;out->z=value;}
void battleGridRemovePokemon(NullSequence *sequence){BattleGridTrainer *entry=gBattleGrid.trainers;ModelSequence *pokemon=asModel(sequence);if(pokemon){for(u16 i=0;i<4;i++,entry++){for(u16 j=0;j<2;j++){if(entry->pokemon[j]==pokemon){entry->pokemon[j]=0;entry->count--;gBattleGrid.pokemonCount--;pokemon->SetVisibility(0);pokemon->flipped=0;lookSource(pokemon,0);return;}}}}}
void battleGridReplacePokemon(NullSequence *oldSequence,NullSequence *newSequence){BattleGridTrainer *entry=gBattleGrid.trainers;ModelSequence *oldModel=asModel(oldSequence),*newModel=asModel(newSequence);if(!oldModel||!newModel){GSlogWrite("battleGridReplacePokemon: NULL argument");return;}for(u16 i=0;i<4;i++,entry++){for(u16 j=0;j<2;j++){if(entry->pokemon[j]==oldModel){lookSource(oldModel,0);entry->pokemon[j]=newModel;lookSource(newModel,entry->trainer);oldModel->SetVisibility(0);newModel->flipped=oldModel->flipped;oldModel->flipped=0;Sequence_CopyState(newSequence,oldSequence);return;}}}}
void battleGridAddPokemon(NullSequence *trainerSequence,NullSequence *pokemonSequence){BattleGridTrainer *entry=gBattleGrid.trainers;ModelSequence *trainer=asModel(trainerSequence),*pokemon=asModel(pokemonSequence);if(!trainer)return;if(!pokemon)return;if(gBattleGrid.pokemonCount<8){for(u16 i=0;i<4;i++,entry++){if(entry->trainer==trainer){if(entry->count>=2)return;for(u16 j=0;j<2;j++){if(!entry->pokemon[j]){entry->pokemon[j]=pokemon;lookSource(pokemon,trainer);entry->count++;gBattleGrid.pokemonCount++;pokemon->flipped=entry->side;return;}}}}}}
void battleGridAddTrainer(NullSequence *sequence,s8 side,s8 lane){ModelSequence *trainer=asModel(sequence);if(trainer&&gBattleGrid.trainerCount<4){BattleGridTrainer *entry=gBattleGrid.trainers;for(u16 i=0;i<4;i++,entry++){if(!entry->trainer)break;}memset(entry,0,16);entry->trainer=trainer;entry->side=side;entry->lane=lane;trainer->flipped=side;gBattleGrid.trainerCount++;}}
}
